def analyze_all():
    for i, (demo_inp, demo_out) in enumerate([(inp_demo1, out_demo1), (inp_demo2, out_demo2), 
                                               (inp_demo3, out_demo3), (inp_demo4, out_demo4)]):
        inp = [[int(x) for x in l.split()] for l in demo_inp.strip().split('\n')]
        out = [[int(x) for x in l.split()] for l in demo_out.strip().split('\n')]

        inp_counts = Counter([v for r in inp for v in r])
        out_counts = Counter([v for r in out for v in r])

        bg = inp_counts.most_common(1)[0][0]
        fg = min(inp_counts.keys(), key=lambda k: inp_counts[k])
        most_out = out_counts.most_common(1)[0][0][0]  # Fix
        least_out = min(out_counts.keys(), key=lambda k: out_counts[k])

        print(f"\nDemo{i+1}:")
        print(f"  Input: bg={bg}({inp_counts[bg]}), fg={fg}")
        print(f"  Output: most_freq={most_out}({out_counts[most_out]}), least_freq={least_out}")

        # Count mapping to outputs based on frequency
        bg_to_most = 0
        bg_to_least = 0
        fg_to_most = 0
        fg_to_least = 0

        for r, row in enumerate(inp):
            for c, val in enumerate(row):
                try:
                    vout = out[r][c]
                except IndexError:
                    continue
                if val == bg:
                    if vout == most_out:
                        bg_to_most += 1
                    elif vout == least_out:
                        bg_to_least += 1
                elif val == fg:
                    if vout == most_out:
                        fg_to_most += 1
                    elif vout == least_out:
                        fg_to_least += 1

        print(f"  bg→most_out: {bg_to_most}, bg→least_out: {bg_to_least}")
        print(f"  fg→most_out: {fg_to_most}, fg→least_out: {fg_to_least}")

analyze_all()

